add('R01-RET-BASIC-3-1','微分方程式と一点の値から二階・三階導関数を求める。',{'関係':m(r"f'(x)=1+f(x)^2"),'初期値':m(r'f(0)=1'),'求める量':m(r"(f''(0),f'''(0))")},[m(s) for s in ['(2,4)','(2,6)','(2,8)','(4,12)','(4,16)']],['f′(0)=2だが二階導関数は2ff′=4である。','二階導関数4に一致しない。','二階導関数4に一致しない。','二階は合うが三階では積の微分の両項を数えると16になる。','二階4、三階16に一致する。'],5,m(r"f'(0)=2,\quad f''=2ff',\quad f'''=2(f')^2+2ff''")+'よりf″(0)=4、f‴(0)=8+8=16となり5である。解fそのものを求める必要はなく、関係式を順に微分すればよい。','微分関係式の繰返し微分','積の微分、連鎖律、一点の初期条件。',['chain'])
add('R01-RET-BASIC-3-4','指定のシンプソン公式で定積分を近似し、最も近い候補を選ぶ。',{'積分':m(r'\int_{-1}^{1}\frac{1}{x+3}\,dx'),'指定重み':'区間両端1/3、中点4/3。'},['0.653','0.663','0.673','0.683','0.693'],['シンプソン近似25/36≈0.69444との差は約0.04144。','差は約0.03144。','差は約0.02144。','差は約0.01144。','差は約0.00144で最も小さい。'],5,m(r'S\approx\frac13\frac12+\frac43\frac13+\frac13\frac14=\frac{25}{36}\approx0.69444')+'となり、最も近い0.693の5を選ぶ。厳密値はln2≈0.693147だが、指定手法の計算結果とは区別する。','指定求積法の近似値と厳密値','シンプソンの重み、3点の関数値、最近傍候補。',['quadrature'],citations=['nist_quadrature'])
vector('R02-REG-BASIC-3-1','多項式ベクトル場の指定点における発散を求める。',{'ベクトル':m(r'V=(x,x^2y+yz^2,z^3)'),'点':'(1,3,2)'},[m(s) for s in ['(-12,0,6)','18','24','(1,15,8)','(1,5,12)']],['回転ベクトルの値であり発散ではない。','対応微分の和1+5+12=18に一致する。','ベクトル場の成分値1+15+8を足した値であり、微分していない。','微分前の成分値を並べたものである。','対応微分を並べており、発散の和を取っていない。'],2,m(r'\operatorname{div}V=1+(x^2+z^2)+3z^2')+'で、指定点では1+5+12=18、2である。発散はスカラーであり、成分微分を並べた(1,5,12)を返す演算ではない。','発散のスカラー性と微分後の評価','多項式の偏微分、微分する変数、スカラーとベクトル。',['divcurl'])
for q,fun,pt,grad,norm,vals,ans in [('R02-REG-BASIC-3-2',r'x^2+2xy+3y^2','(1,1)','(4,8)',r'4\sqrt5',['6','(4,8)','12',r'4\sqrt5',r'\sqrt2'],4),('R07-REG-BASIC-3-2',r'2x^2+xy-y^2','(2,1)','(9,0)','9',['9','3',r'\sqrt5','(9,0)',r'\sqrt{26}'],1)]:
 derivative=r'(2x+2y,2x+6y)' if ans==4 else r'(4x+y,x-2y)'
 vector(q,'二変数関数の指定点における最急勾配の長さを求める。',{'関数':m('f(x,y)='+fun),'点':pt,'求める量':'勾配ベクトルのユークリッドノルム。'},[m(v) for v in vals],['偏微分してノルムを取ると'+norm+'となり一致しない。' if i!=ans and v!=grad else ('勾配ベクトルそのものであり長さではない。' if v==grad else '勾配ベクトルの二乗和の平方根に一致する。') for i,v in enumerate(vals,1)],ans,'勾配は'+m(r'\operatorname{grad}f='+derivative)+'で、指定点では'+m(grad)+'である。そのノルムは'+m(norm)+'なので'+str(ans)+'を選ぶ。方向を表すベクトルと、最大方向微分の値である長さを分ける。','勾配と最急上昇率のノルム','偏微分、方向微分、ユークリッドノルム。',['gradient'])
vector('R03-REG-BASIC-3-1','三次元ベクトル場の指定点における回転ベクトルを求める。',{'ベクトル':m(r'V=(y+z,x^2+y^2+z^2,z+2y)'),'点':'(2,3,1)','座標':'右手系の三次元直交座標。'},[m(s) for s in ['7','(0,6,1)','4','(0,1,3)','(4,14,7)']],['発散1+2y=7の値であり、回転ではない。','回転の成分微分の組合せが違う。','回転はベクトルであり単一数ではない。','(2−2z,1,2x−1)の点での値に一致する。','元のベクトル場の成分値であり微分していない。'],4,m(r'\operatorname{rot}V=(\partial_yV_z-\partial_zV_y,\partial_zV_x-\partial_xV_z,\partial_xV_y-\partial_yV_x)=(2-2z,1,2x-1)')+'となる。点(2,3,1)で(0,1,3)、4を選ぶ。第2成分の差の順序も成分式から確認する。','三次元回転ベクトルの成分','偏微分、右手系、交差微分の差、発散との違い。',['divcurl'])
add('R03-REG-BASIC-3-2','任意の三次以下の多項式を区間−1〜1で正確に積分する式を選ぶ。',{'関数':m(r'f(x)=ax^3+bx^2+cx+d'),'係数':'a,b,c,dは任意の実数。','積分区間':'−1〜1。'},[m(s) for s in ['2f(0)',r'f(-\sqrt{1/3})+f(\sqrt{1/3})','f(-1)+f(1)',r'\frac12f(-\sqrt{3/5})+\frac89f(0)+\frac12f(\sqrt{3/5})',r'\frac12f(-1)+f(0)+\frac12f(1)']],['2dでありbx²の積分2b/3が抜ける。','奇関数部分は相殺し、2b/3+2dに一致する二点ガウス求積である。','2b+2dとなりbx²の係数が大きすぎる。','定数の重み和が17/9で2に足りず、x²の係数も3/5で2/3と異なる。正しい三点ガウスの両端重み5/9とは違う。','b+2dとなりbx²の係数が合わない。'],2,'対称区間では奇関数項の積分が0なので厳密値は2b/3+2dである。2では評価点の二乗が1/3なので'+m(r'f(-1/\sqrt3)+f(1/\sqrt3)=2b/3+2d')+'となる。4はガウスの評価点に似ているが両端の重みが1/2であり、正しい求積式ではない。','求積公式の多項式モーメント条件','奇偶性、多項式の積分、二点ガウス求積、重みの検算。',['quadrature'],citations=['nist_quadrature'])
vector('R04-REG-BASIC-3-2','任意の三次元ベクトルに必ずしも成立しない恒等式を選ぶ。',{'ベクトル':'三次元直交座標の任意の実ベクトルa,b。','演算':'内積と外積を区別する。','方向':'全てのa,bで成立するとは限らないもの。'},[m(s) for s in [r'(a\times b)\cdot a=0',r'a\times b=b\times a',r'a\cdot b=b\cdot a',r'b\cdot(a\times b)=0',r'a\times a=0']],['外積はaへ垂直であり成立する。','外積は反交換的で、a×b=−b×aである。平行な場合のゼロを除き一般には成立しない。','実ベクトルの内積は交換的であり成立する。','外積はbへも垂直であり成立する。','同じベクトルの外積はゼロであり成立する。'],2,'a=(1,0,0)、b=(0,1,0)とするとa×b=(0,0,1)、b×a=(0,0,−1)である。2には反例がある。特殊な平行ベクトルで一致しても「任意」での恒等式にはならない。','内積の交換性と外積の反交換性','外積の右手方向、垂直性、恒等式と反例。',['projection'],verdicts=['恒等的に正しい','一般には誤り','恒等的に正しい','恒等的に正しい','恒等的に正しい'])
add('R05-REG-BASIC-3-2','四分の一円領域でxの二重積分を求める。',{'領域':m(r'0\le x\le1,0\le y\le\sqrt{1-x^2}'),'積分':m(r'\int\int_R x\,dxdy')},[m(s) for s in [r'\pi/3','1/3',r'\pi/2',r'\pi/4','1/4']],['xを重みにした積分は円の角度や単なる面積と異なる。','積分x√(1−x²)を0〜1で評価した1/3に一致する。','半円の面積に相当し領域・被積分関数が違う。','四分の一円の面積であり、xという重みを落としている。','同じ領域でのxの平均を単に1/πと仮定する根拠はない。積分で求めると1/3である。'],2,'y方向に先に積分すると'+m(r'\int_0^1x\sqrt{1-x^2}\,dx')+'となる。t=1−x²、dt=−2xdxと置けば'+m(r'\frac12\int_0^1\sqrt t\,dt=1/3')+'で2を選ぶ。領域面積π/4と重み付き積分を混同しない。','領域を読んだ累次積分と置換積分','四分の一円、積分順序、変数置換、面積と一次モーメント。',['jacobian','quadrature'])
add('R06-REG-BASIC-3-1','連鎖律で偏微分ベクトルを変換する2行2列行列を選ぶ。',{'関係':m(r'f=f(x,y),g=g(x,y),u=u(f,g)'),'向き':'(ux,uy)の列=J(uf,ug)の列。','候補表記':'下付きは偏微分、セミコロンは行区切り。'},[m(s) for s in ['(x_f,y_f;x_g,y_g)','(f_x,f_y;g_x,g_y)','(u_f,u_g;u_x,u_y)','(f_x,g_x;f_y,g_y)','(x_f,x_g;y_f,y_g)']],['逆向きの座標関数の微分を使っている。','行列を転置する必要があり、出力の各行がxとyになっていない。','変換される関数uそのものの微分を係数としており、連鎖律の行列ではない。','ux=uf fx+ug gx、uy=uf fy+ug gyに一致する。','逆向きの変換の係数であり、原典の向きとは違う。'],4,'連鎖律を一行ずつ書くと'+m(r'u_x=u_ff_x+u_gg_x,u_y=u_ff_y+u_gg_y')+'である。従ってJの行は(fx,gx)、(fy,gy)で4を選ぶ。ヤコビ行列という名前より、与えられた列ベクトルの掛け算を優先して向きを定める。','連鎖律の行列表示と転置','合成関数の微分、行列積、微分する変数の順序。',['chain'],citations=['mit_chain2007'])
vector('R06-REG-BASIC-3-2','点aから単位ベクトルbの張る直線へ向かう垂線ベクトルを選ぶ。',{'始点':'aの終点。','終点':'原点を通りb方向の直線上の垂足。','条件':m(r'|b|=1')},[m(s) for s in [r'a\times b',r'(b\cdot a)b-a','b-a',r'(b\cdot a)b',r'a\times b-a']],['a,bの両方に垂直な向きであり、aから直線上の垂足への変位ではない。','垂足の位置(b·a)bから始点aを引いたベクトルに一致する。','終点をbの端点に固定しており、その点が垂足である保証がない。','原点から垂足への位置ベクトルであり、始点aからの変位ではない。','終点a×bは一般にb方向の直線上にない。'],2,'垂足の位置は単位bへの射影'+m(r'p=(a\cdot b)b')+'である。求めるベクトルは始点aから終点pへのp−a、2である。その内積'+m(r'(p-a)\cdot b=(a\cdot b)|b|^2-a\cdot b=0')+'で垂直性も検算できる。','直線への射影と始点からの変位','単位方向ベクトル、内積、垂足、終点−始点。',['projection'])
matrix('R07-REG-BASIC-3-1','パラメータを含む上三角行列の逆行列を選ぶ。',{'行列A':m(r'(1,a,a^2;0,1,a;0,0,1)'),'条件':m(r'a\neq0')+'の実数。','表記':'セミコロンで行を区切る。'},[m(s) for s in ['(1,-a,-a^2;0,1,-a;0,0,1)','(1,-a,0;0,1,-a;0,0,1)','(1,a,0;0,1,a;0,0,1)','(1,0,-a^2;0,1,0;0,0,1)','(1,-a,a^2;0,1,-a;0,0,1)']],['積の第1行第3列が−a²でゼロにならない。','上の非対角−aを打ち消し、第1行第3列も−a²+a²=0となる。','第1行第2列と第2行第3列の符号が違う。','隣接する非対角aを打ち消す−aがない。','積の第1行第3列がa²でゼロにならない。'],2,'逆の第1行第2列と第2行第3列は−aである。第1行第3列をqとすると積のそこはq+a(−a)+a²=qなのでq=0、2を選ぶ。元のa²をそのまま符号反転すると結合項を二重に数える。','上三角行列の逆と結合項の相殺','行列積、正則性、上三角行列。',['inverse'],citations=['mit_inverse2007'])
add('R07-REG-BASIC-3-3','等間隔の3点を使うシンプソン法の式を選ぶ。',{'点':m(r'b=a+h,c=a+2h,h>0'),'区間':'aからc、全幅2h。','方式':'2次のニュートン・コーツ閉公式。'},[m(s) for s in [r'\frac h2(f(a)+f(c))',r'h(f(a)+f(c))',r'\frac h6(f(a)+4f(b)+f(c))',r'\frac h4(f(a)+4f(b)+f(c))',r'\frac h3(f(a)+4f(b)+f(c))']],['全幅2hに対する台形則の半分であり、シンプソン法でもない。','これは全幅2hに対する台形則で、中点を使わない。','重みの和がhとなり、定数関数の積分2hに足りない。','重みの和が3h/2で、定数関数の積分2hに足りない。','両端1・中点4の重みへh/3を掛けるシンプソン法に一致する。'],5,'3点を通る二次補間多項式を積分すると'+m(r'\frac h3[f(a)+4f(b)+f(c)]')+'となり5である。全幅は2hなので、全幅をHと書く別の表現なら係数H/6となる。記号の定義を読み替えずh/6を選ばない。','区間幅の定義とシンプソン重み','二次補間、等間隔の3点、定数関数の検算。',['quadrature'],figure=True,citations=['nist_quadrature'])
