(ROOT/'config/authored_batches/S7_009_mathematics.json').write_text(json.dumps(dict(batch_id='S7_009_mathematics',reference_date='2026-10-09',scope='基礎解析29問。原典21ページ画像の全式・符号・全5肢を確認。解答と理由を独立作成後に公式と照合。H28ヤコビアンの面積絶対値と領域の不足を部分校正。',questions=items),ensure_ascii=False,indent=2)+'\n')
